class BookInventory { private final int copiesTotal; private int copiesAvailable; BookInventory(int n){if(n<=0)throw new IllegalArgumentException();copiesTotal=n;copiesAvailable=n;} void checkOut(){if(copiesAvailable>0)copiesAvailable--;} void checkIn(){if(copiesAvailable<copiesTotal)copiesAvailable++;} int getCopiesAvailable(){return copiesAvailable;} } public class Problem3{public static void main(String[]x){BookInventory b=new BookInventory(3);b.checkOut();b.checkOut();b.checkOut();b.checkOut();System.out.println(b.getCopiesAvailable());b.checkIn();b.checkIn();b.checkIn();b.checkIn();System.out.println(b.getCopiesAvailable());}}
